function textoLegal(){
  const b = esc(Store.s.config.nombre || 'Bahía Cauquén');
  return LEGAL.map(([t, ps]) => `<h3>${esc(t)}</h3>${ps.map(p => `<p>${esc(p).replace(/\{BARRIO\}/g, b)}</p>`).join('')}`).join('');
}

R.legal = {
  titulo: 'Términos de uso y responsabilidad', icon: 'file', color: 'brand', sub: 'Datos personales y deslinde de responsabilidad del autor',
  render(){
    return `<div class="card legal">
        <p class="legal-cab"><b>Términos y condiciones de uso, política de protección de datos personales y deslinde de responsabilidad</b>
          <span>Versión del ${VERSION_LEGAL} · Ushuaia, Tierra del Fuego, Antártida e Islas del Atlántico Sur</span></p>
        ${textoLegal()}
        <p class="legal-firma">Claudio A. Ravasi<br><span>Autor de la Aplicación</span></p>
      </div>
      <div class="btns" style="margin-top:12px"><button class="btn btn-sec grow" data-a="legal-pdf">${I('file')}Descargar o imprimir</button>
        <button class="btn btn-sec grow" data-a="abrir" data-v="aporte">${I('heart')}Publicidad y aporte al barrio</button></div>`;
  },
};
/* Desde la inscripción (todavía sin cuenta): se lee en una hoja. */
A['ver-legal'] = () => hoja('Términos de uso y responsabilidad', `<div class="legal"><p class="legal-cab"><b>Términos y condiciones de uso, política de protección de datos personales y deslinde de responsabilidad</b><span>Versión del ${VERSION_LEGAL}</span></p>${textoLegal()}</div>
  <button class="btn btn-pri btn-block" data-a="cerrar-hoja" style="margin-top:12px">Entendido</button>`, { ancho:'760px' });
A['legal-pdf'] = () => imprimir('Términos de uso y responsabilidad', `<h1>Barrio ${esc(Store.s.config.nombre)}</h1>
  <p><b>Términos y condiciones de uso, política de protección de datos personales y deslinde de responsabilidad</b><br>Versión del ${VERSION_LEGAL}</p>
  ${textoLegal().replace(/<h3>/g, '<h2>').replace(/<\/h3>/g, '</h2>')}
  <p style="margin-top:28px"><b>Claudio A. Ravasi</b><br>Autor de la Aplicación</p>`);

/* =========================================================
   PROTECCIÓN DE DATOS: LO QUE LE TOCA AL BARRIO
   La app pone las herramientas; hay obligaciones que son del barrio como
   responsable de la base (Ley 25.326). Esta ventana (solo Administración)
   las ordena: la inscripción en el Registro Nacional de Bases de Datos de la
   AAIP con las respuestas ya redactadas, quién atiende los pedidos de los
   vecinos, el compromiso de confidencialidad para imprimir y firmar, y un
   registro de incidentes de seguridad. Todo queda en config.proteccion.
   ========================================================= */
const cfgDatos = () => Object.assign({ inscripta:false, inscripcionFecha:'', inscripcionNro:'', responsableArco:'', compromisosFirmados:false, compromisosFecha:'', incidentes:[], sacadasBorradas:0 }, Store.s.config.proteccion || {});
function tareasDatosPendientes(){ const c = cfgDatos(); return [!c.inscripta, !c.responsableArco, !c.compromisosFirmados, !c.sacadasBorradas].filter(Boolean).length; }
const RESPUESTAS_AAIP = () => {
  const c = Store.s.config;
  return [
    ['Responsable de la base', `Barrio ${c.nombre} (entidad administradora), CUIT ${c.cuit || '—'}, domicilio ${c.domicilio || '—'}, correo ${c.adminEmail || '—'}.`],
    ['Nombre de la base', `Vecinos, visitas y administración del Barrio ${c.nombre}.`],
    ['Finalidad', 'Comunicación entre vecinos y con la Administración, seguridad y control de acceso al barrio, administración y cobro de expensas, y convivencia del barrio.'],
    ['Datos que se tratan', 'Identificatorios (nombre, DNI, lote, correo, teléfono optativo); la guía del barrio (quién vive en cada lote, si es propietario o inquilino, la dirección del lote y los teléfonos de contacto, que ven solo la garita, la Administración y la supervisión); de visitas (nombre, DNI y patente, borrados a los ' + (c.datosDias || 90) + ' días); de pagos de expensas; ubicación solo al pedir un SOS; del personal de guardia y del policía contratado (nombre, matrícula, celular para enviarle su código de ronda, correo para enviarle la constancia de su servicio, día, turno y hora de ingreso y de salida, y rondas con la hora de cada punto de control); de los viajes de Uber, DiDi o taxi que avisa un vecino (aplicación, patente, nombre del chofer si se anota y horario). No se tratan datos sensibles salvo el tipo de emergencia de un SOS, informado por el propio titular.'],
    ['Origen de los datos', 'Los aporta el propio titular al inscribirse o al usar la app; los de visitas, el vecino que las anuncia o la propia visita; los del padrón, la liquidación de expensas del barrio; los de la guía del barrio, el listado general de lotes que lleva la Administración.'],
    ['Cesiones', 'No se ceden datos a terceros, salvo obligación legal u orden judicial. El Hotel Los Cauquenes, que usa la app con una cuenta institucional, no accede a los datos de los vecinos.'],
    ['"Estoy bien" y aviso de salida (voluntarios)', 'Nombre, lote, teléfono, hora límite elegida, familiares (nombre, correo y teléfono), personas del barrio elegidas, hora del aviso diario y, en una salida, actividad, lugar, acompañantes y hora de regreso. Los ven solo el titular, la garita, la Administración y las personas del barrio que eligió; los familiares reciben un correo. Finalidad: avisarles si no confirma. Se borran a los 30 días o al dar de baja la función. No incluyen datos de salud.'],
    ['Servicio del policía contratado', 'Nombre, matrícula, celular, correo, día, turno y hora de ingreso y de salida, guardias del turno, rondas con la hora de cada punto de control y lo que anotó la garita. Los ven solo la garita y la Administración. Finalidad: controlar y acreditar el servicio; al terminar, se le envía la constancia a su propio correo. Se conservan en el libro de guardia.'],
    ['Lotes alquilados', 'Relación de cada cuenta con su lote (propietario, cotitular, inquilino o familiar). Finalidad: que el día a día del lote lo maneje quien vive en él y que el propietario vea lo que le toca como titular (expensas, votaciones, comunicados). El propietario no residente no recibe los datos del día a día de la vivienda.'],
    ['Correos que ingresan al barrio', 'Empresa y hora de entrada y de salida (las ven los vecinos; se borran a los 30 días). En el libro de guardia: patente optativa del vehículo y lotes a los que va (garita, Administración y supervisión). Las cuentas de esos lotes reciben un aviso con la empresa y la hora. Finalidad: seguridad del acceso y que el vecino sepa que llega su envío.'],
    ['Ausencias ("Me voy de viaje")', 'Fechas en que la casa queda sola, un contacto y una nota, y cada revisión diaria de la guardia. Los ven solo el vecino, las cuentas de su lote, la garita y la Administración. Se borran dos días después del regreso.'],
    ['Vecinos del equipo de salud (voluntario)', 'Marca de que sabe primeros auxilios o es del equipo de salud y su profesión. Finalidad: avisarle cuando la garita sale con el DEA. Si responde que va, la garita y el vecino que pidió ayuda ven su nombre, profesión y teléfono.'],
    ['Datos de huéspedes del hotel', 'Nombre, fechas de estadía, patente y vuelos, que carga el hotel (responsable de esos datos). Los ven solo el hotel y la garita, para el ingreso y los traslados; la Administración, solo la cantidad. Se eliminan al día siguiente del egreso.'],
    ['Supervisor de la guardia', 'Una cuenta personal por cada supervisor que designa la Administración, con un rol que solo permite mirar. Ve en tiempo real lo que ve la garita para controlar el servicio: ingresos y egresos con los datos de las visitas, bitácora, turnos, rondas del policía, peticiones firmadas, casas solas para revisar, SOS con su ubicación y pedidos del DEA, y nombre, lote, dirección y teléfonos de cada lote (guía del barrio). Solo puede escribirles mensajes a la garita y a la Administración y dar el visto a cada parte de turno. Recibe alertas automáticas del servicio y un informe mensual por correo sin lotes, nombres, DNI ni patentes de vecinos (también va a la Administración, si lo elige). No ve los mensajes privados de los vecinos, ni "Estoy bien", ni los huéspedes del hotel, ni expensas o pagos. Firma el compromiso de confidencialidad (art. 10). Las alertas y los vistos se conservan con el libro de guardia.'],
    ['Publicidad', 'La app puede mostrar promociones y publicidad de comercios, pero no trata datos con fines de publicidad (art. 27): no comparte datos de los vecinos con los anunciantes, no arma perfiles ni elige los anuncios según quién mira, y no usa rastreadores publicitarios.'],
    ['Transferencia internacional', 'Sí: los datos se alojan en servidores de Google LLC (Firebase) en los Estados Unidos, que actúa como prestador de servicios (art. 25). La transferencia cuenta con el consentimiento expreso de los titulares (art. 12 de la Ley 25.326 y art. 12 del Decreto 1558/2001).'],
    ['Medidas de seguridad', 'Conexiones cifradas (HTTPS/TLS); almacenamiento cifrado por el proveedor; contraseñas guardadas solo como huella irreversible; reglas de acceso en el servidor por rol; cada vecino accede solo a sus datos; registro de auditoría; borrado automático de datos de visitas; compromiso de confidencialidad del personal con acceso.'],
    ['Conservación', 'Datos de visitas: ' + (c.datosDias || 90) + ' días. Datos contables y de expensas: 10 años (art. 328 del Código Civil y Comercial). Avisos de "Estoy bien": 30 días. El resto, mientras el titular tenga cuenta.'],
    ['Derechos de los titulares', 'Acceso, rectificación, actualización y supresión, gratuitos, ante la Administración' + (cfgDatos().responsableArco ? ` (${cfgDatos().responsableArco})` : '') + '. Plazos: 10 días corridos para el acceso y 5 días hábiles para rectificar o suprimir.'],
  ];
};
R.proteccion = {
  titulo: 'Protección de datos', icon: 'lock', color: 'ok', sub: 'Lo que le toca al barrio como responsable de la base',
  render(){
    if (!esAdmin()) return vacio('lock', 'Solo para la Administración.');
    const c = cfgDatos();
    const paso = (ok, t, x) => `<div class="it"><span class="ic ic-${ok ? 'ok' : 'warn'}" style="width:34px;height:34px;border-radius:11px;display:grid;place-items:center">${I(ok ? 'check' : 'alert')}</span><div class="txt"><b>${t}</b><span>${x}</span></div></div>`;
    return `<p class="muted small" style="margin:0 0 12px">La app ya cumple su parte (cifrado, acceso por rol, borrado de visitas, auditoría). Estas tareas son del barrio como responsable de la base de datos (Ley 25.326). Van también en Preguntas frecuentes, para que los vecinos sepan que se hacen.</p>
      <div class="card lista">
        ${paso(c.inscripta, 'Base inscripta en el Registro Nacional de Bases de Datos (AAIP)', c.inscripta ? `Inscripta${c.inscripcionFecha ? ' el ' + fechaCorta(c.inscripcionFecha) : ''}${c.inscripcionNro ? ' · N.º ' + esc(c.inscripcionNro) : ''}` : 'Pendiente. Es lo que hace lícito el archivo (arts. 3 y 21).')}
        ${paso(!!c.responsableArco, 'Quién atiende los pedidos de los vecinos sobre sus datos', c.responsableArco ? esc(c.responsableArco) : 'Pendiente: nombre y correo de quien responde (10 días corridos para el acceso, 5 hábiles para corregir o borrar).')}
        ${paso(c.compromisosFirmados, 'Compromiso de confidencialidad firmado por guardias, supervisores y Administración', c.compromisosFirmados ? `Firmados${c.compromisosFecha ? ' el ' + fechaCorta(c.compromisosFecha) : ''}` : 'Pendiente (art. 10: deber de secreto). Imprimilo abajo.')}
        ${paso(true, 'Registro de incidentes de seguridad', `${plural(aLista(c.incidentes).length, 'incidente anotado', 'incidentes anotados')}`)}
        ${paso(!!c.sacadasBorradas, 'Borrar lo que quedó del chat vecinal y de las reservas', c.sacadasBorradas ? `Borrado el ${fechaCorta(isoDe(new Date(c.sacadasBorradas)))}` : 'Pendiente. Esas dos funciones se sacaron de la app el 29-09-2026; lo que quedó guardado en la base ya no tiene finalidad y hay que borrarlo (art. 4 inc. 7).')}
      </div>
      ${c.sacadasBorradas ? '' : `<div class="btns"><button class="btn btn-sm btn-danger-soft" data-a="datos-sacados-borrar">${I('trash')}Borrar lo que quedó del chat y las reservas</button></div>`}
      ${sec('Cómo inscribir la base en la AAIP')}
      <div class="card small" style="line-height:1.6">
        <p style="margin:0 0 8px">1. Entrá a <b>argentina.gob.ar/aaip/datospersonales</b> y buscá la inscripción de bases de datos en el Registro Nacional de Bases de Datos. El trámite es en línea y gratuito, con la <b>clave fiscal de la entidad del barrio</b> (CUIT ${esc(Store.s.config.cuit || '—')}), por Trámites a Distancia (TAD).</p>
        <p style="margin:0 0 8px">2. Te van a preguntar lo de abajo: las respuestas ya están redactadas con lo que hace la app. Copialas.</p>
        <p style="margin:0">3. Cuando termines, anotá acá la fecha y el número. Si cambia algo importante (otra finalidad, otro proveedor), hay que actualizar la inscripción.</p>
        <p class="muted tiny" style="margin:10px 0 0">El nombre exacto de los pasos puede cambiar en el sitio de la AAIP; lo que se declara es siempre esto.</p></div>
      <div class="card lista">${RESPUESTAS_AAIP().map(([t, x], i) => `<div class="it"><div class="txt"><b>${esc(t)}</b><span style="white-space:normal">${esc(x)}</span></div><button class="icon-btn" data-a="aaip-copiar" data-v="${i}" aria-label="Copiar">${I('copy')}</button></div>`).join('')}</div>
      <div class="btns"><button class="btn btn-sm btn-sec" data-a="aaip-imprimir">${I('file')}Imprimir las respuestas</button></div>
      ${sec('Anotar lo hecho')}
      <form data-f="proteccion" class="card">
        <label class="check"><input type="checkbox" name="inscripta" ${c.inscripta ? 'checked' : ''}><span>La base ya está inscripta en la AAIP</span></label>
        <div class="grid2"><div class="field"><label>Fecha de inscripción</label><input type="date" name="inscripcionFecha" value="${esc(c.inscripcionFecha)}"></div>
          <div class="field"><label>Número de registro</label><input name="inscripcionNro" maxlength="40" value="${esc(c.inscripcionNro)}"></div></div>
        <div class="field"><label>Quién atiende los pedidos sobre datos (nombre y correo)</label><input name="responsableArco" maxlength="120" value="${esc(c.responsableArco)}" placeholder="Paula Juncos · barriobahiacauquen@gmail.com"></div>
        <label class="check"><input type="checkbox" name="compromisosFirmados" ${c.compromisosFirmados ? 'checked' : ''}><span>Guardias, supervisores y Administración firmaron el compromiso de confidencialidad</span></label>
        <div class="field"><label>Fecha de las firmas</label><input type="date" name="compromisosFecha" value="${esc(c.compromisosFecha)}"></div>
        <button class="btn btn-pri btn-block">${I('check')}Guardar</button></form>
      ${sec('Compromiso de confidencialidad')}
      ${superficie({ a:'compromiso-imprimir', icon:'file', color:'brand', t:'Imprimir el compromiso', s:'Uno por persona: guardias (también los que cubren francos), supervisores de la guardia y quienes administran' })}
      ${sec('Registro de incidentes', `<button class="link" data-a="incidente-nuevo">Anotar un incidente</button>`)}
      ${aLista(c.incidentes).length ? `<div class="card lista">${aLista(c.incidentes).slice().reverse().map(x => `<div class="it"><div class="txt"><b>${fechaCorta(x.fecha)} · ${esc(x.que)}</b><span style="white-space:normal">Afectados: ${esc(x.afectados || '—')} · Medidas: ${esc(x.medidas || '—')}${x.avisados ? ' · Se avisó a los afectados' : ''}</span></div></div>`).join('')}</div>`
        : vacio('lock', 'Sin incidentes. Anotá cualquiera: una contraseña que se filtró, un teléfono de la garita perdido, un acceso que no correspondía.')}
      <p class="muted tiny">Ante un incidente: cambiar las contraseñas involucradas, sacar el acceso a quien no corresponde, avisar a los vecinos afectados y dejarlo anotado acá (Resolución AAIP 47/2018).</p>`;
  },
};
/* LO QUE QUEDÓ DE DOS FUNCIONES QUE SE SACARON (29-09-2026)
   El chat vecinal y las reservas de espacios comunes ya no están en la app:
   ningún equipo baja ni escribe esas carpetas, y las reglas se las cierran a
   todos menos a la Administración. Lo que quedó guardado ya no tiene
   finalidad (art. 4 inc. 7 de la Ley 25.326), así que se borra. No se borra
   solo porque es para siempre: lo hace la Administración con un botón, y
   queda en la auditoría. */
const CARPETAS_SACADAS = ['msgs', 'reservas', 'bloqueos', 'amenities'];
A['datos-sacados-borrar'] = async () => {
  if (!esAdmin()) return;
  if (!await confirmar('Borrar el chat vecinal y las reservas', 'Se borran para siempre los mensajes del chat vecinal y las reservas, los turnos bloqueados y los espacios comunes que quedaron guardados en la base. Esas funciones ya no están en la app. No se puede deshacer.', { si:'Borrar para siempre', peligro:true })) return;
  if (Nube.activa()){
    if (!Nube.db){ toast('Sin conexión con la base: probá de nuevo en un rato', 'alert'); return; }
    try { await Promise.all(CARPETAS_SACADAS.map(k => Nube.db.ref('barrio/' + k).remove())); }
    catch(e){ toast('No se pudo borrar (¿faltan publicar las reglas?)', 'alert'); console.warn('Borrar carpetas sacadas', e.message); return; }
  }
  Store.cambiar(s => { s.config.proteccion = Object.assign({}, cfgDatos(), { sacadasBorradas:Date.now() });
    auditar(s, 'Borró lo que quedaba del chat vecinal y de las reservas', 'Funciones que se sacaron de la app el 29-09-2026'); });
  toast('Listo: se borró lo que quedaba del chat y de las reservas', 'trash'); refrescar();
};
A['aaip-copiar'] = el => { const r = RESPUESTAS_AAIP()[+el.dataset.v]; if (!r) return; try { navigator.clipboard.writeText(r[1]); } catch(e){} toast(`Copiado: ${r[0]}`, 'copy'); };
A['aaip-imprimir'] = () => imprimir('Inscripción en la AAIP', `<h1>Barrio ${esc(Store.s.config.nombre)}</h1><p><b>Respuestas para la inscripción de la base en el Registro Nacional de Bases de Datos (AAIP)</b><br>${fechaLarga(hoyISO())}</p>
  ${RESPUESTAS_AAIP().map(([t, x]) => `<h2>${esc(t)}</h2><p>${esc(x)}</p>`).join('')}`);
F['proteccion'] = d => {
  Store.cambiar(s => { s.config.proteccion = Object.assign({}, cfgDatos(), { inscripta:!!d.inscripta, inscripcionFecha:d.inscripcionFecha || '', inscripcionNro:String(d.inscripcionNro || '').trim(),
    responsableArco:String(d.responsableArco || '').trim(), compromisosFirmados:!!d.compromisosFirmados, compromisosFecha:d.compromisosFecha || '' });
    auditar(s, 'Actualizó las tareas de protección de datos', ''); });
  toast('Guardado', 'check'); refrescar();
};
A['incidente-nuevo'] = () => hoja('Anotar un incidente de seguridad', `<form data-f="incidente">
  <div class="field"><label>Fecha</label><input type="date" name="fecha" required value="${hoyISO()}"></div>
  <div class="field"><label>Qué pasó</label><textarea name="que" required maxlength="400" placeholder="Ej: se perdió el teléfono de la garita con la sesión abierta."></textarea></div>
  <div class="field"><label>A quiénes afecta</label><input name="afectados" maxlength="200"></div>
  <div class="field"><label>Qué se hizo</label><textarea name="medidas" maxlength="400" placeholder="Ej: se cambió la contraseña de la garita y se cerró la sesión en todos los equipos."></textarea></div>
  <label class="check"><input type="checkbox" name="avisados"><span>Se avisó a los afectados</span></label>
  <button class="btn btn-pri btn-block">${I('check')}Anotar</button></form>`);
F['incidente'] = d => {
  Store.cambiar(s => { const c = cfgDatos(); s.config.proteccion = Object.assign({}, c, { incidentes:[...aLista(c.incidentes), { id:uid(), fecha:d.fecha, que:d.que.trim(), afectados:(d.afectados || '').trim(), medidas:(d.medidas || '').trim(), avisados:!!d.avisados, at:Date.now() }] });
    auditar(s, 'Anotó un incidente de seguridad', d.que.trim().slice(0, 80)); });
  cerrarHoja(); toast('Incidente anotado', 'check'); refrescar();
};
/* `nombre` y `cargo` (07-10): el de la supervisión sale con su nombre y su función ya puestos. */
const compromisoHTML = ({ nombre = '', cargo = '' } = {}) => { const c = Store.s.config;
  return `<h1>Barrio ${esc(c.nombre)}</h1><p><b>Compromiso de confidencialidad sobre datos personales</b></p>
  <p>En la ciudad de Ushuaia, a los ____ días del mes de ______________ de 20____, quien suscribe, ${nombre ? '<b>' + esc(nombre) + '</b>' : '____________________________________________'}, DNI ______________, en su carácter de ${cargo ? '<b>' + esc(cargo) + '</b>' : '______________________ (guardia / supervisor de la guardia / integrante de la Administración / otro)'}, declara:</p>
  <p>1. Que en el ejercicio de su función accede a datos personales de los vecinos, de sus visitas y de terceros, a través de la aplicación del Barrio ${esc(c.nombre)} y de otros registros del barrio.</p>
  <p>2. Que se obliga a guardar secreto sobre esos datos, conforme el art. 10 de la Ley 25.326 de Protección de los Datos Personales, y que esta obligación subsiste aun después de finalizada su relación con el barrio.</p>
  <p>3. Que usará los datos exclusivamente para las tareas de su función (seguridad, control de acceso, administración), y que no los copiará, fotografiará, reenviará ni comunicará a terceros, salvo orden judicial o de autoridad competente.</p>
  <p>4. Que mantendrá en reserva su contraseña, no dejará la sesión abierta en equipos sin supervisión, y avisará de inmediato a la Administración ante la pérdida de un equipo o cualquier acceso indebido.</p>
  <p>5. Que conoce que el acceso ilegítimo a un banco de datos personales o la revelación de su contenido pueden constituir delito (arts. 153 bis y 157 bis del Código Penal), sin perjuicio de la responsabilidad civil y de las sanciones que correspondan.</p>
  <p style="margin-top:48px">Firma: ______________________________ &nbsp;&nbsp; Aclaración: ______________________________</p>
  <p style="margin-top:28px">Por la Administración del Barrio: ______________________________</p>`; };
A['compromiso-imprimir'] = el => { const u = el && el.dataset && el.dataset.id ? usuario(el.dataset.id) : null;
  imprimir('Compromiso de confidencialidad', compromisoHTML(u ? { nombre:u.nombre, cargo:'supervisor/a de la guardia' } : {})); };

/* =========================================================
   PUBLICIDAD Y APORTE DEL 50 % AL BARRIO (pedido de Claudio, 07-10-2026)
   -------------------------------------------------------
   Los términos (punto 4) dicen que el Autor se reserva lo que paguen los
   comercios por publicar en la app y que dona la mitad a la Asociación
   Civil del barrio, con destino de bien común. Acá está:
     · la explicación en pocas palabras, para cualquier vecino;
     · el COMPROMISO DE DONACIÓN CON CARGO completo, para leer y para
       imprimir y firmar (Autor + Asociación Civil);
     · el registro de lo donado, que carga la Administración y ven todos.
   La Asociación Civil es sin fines de lucro (art. 168 CCyC): no vende la
   publicidad ni firma con los comercios; recibe una donación con cargo.
   Todo en config.aporte (solo la Administración la escribe).
   ========================================================= */
const COMPROMISO_APORTE = [
  ['Antecedentes', [
    'I. El Autor desarrolló la aplicación web progresiva "Barrio {BARRIO}" (en adelante, "la Aplicación"), obra de su autoría protegida por las Leyes 11.723 y 25.036, y la puso a disposición del Barrio mediante una licencia de uso gratuita, en los términos y condiciones publicados en la propia Aplicación.',
    'II. La Aplicación puede alojar publicidad, promociones, beneficios, patrocinios y enlaces de comercios, empresas y prestadores (en adelante, "los Anunciantes"). El punto 4 de los términos y condiciones reserva al Autor la comercialización de esos espacios y la percepción de lo que generen, y lo obliga a donar la mitad de lo obtenido a la Asociación.',
    'III. La Asociación es una persona jurídica privada sin fines de lucro (art. 168 del Código Civil y Comercial de la Nación, en adelante "CCyC"): no explota comercialmente la Aplicación ni es parte de los contratos con los Anunciantes, pero puede recibir donaciones afectadas a su objeto y al bien común de sus asociados.',
    'IV. Es voluntad del Autor destinar la mitad de lo que se obtenga por esos conceptos al bien común del Barrio, en forma documentada, transparente y verificable, y es voluntad de la Asociación aceptarlo con las condiciones que siguen.',
  ]],
  ['Primera. Objeto', [
    'El Autor dona a la Asociación, y la Asociación acepta (arts. 1542 y 1545 del CCyC), el cincuenta por ciento (50 %) de los Ingresos Comerciales Netos que el Autor perciba mientras rija este compromiso, con el cargo de destino establecido en la cláusula cuarta (arts. 1563 y 1564 del CCyC).',
  ]],
  ['Segunda. Definiciones', [
    'a) Ingresos Comerciales: las sumas que el Autor perciba efectivamente, por cualquier concepto, de terceros que paguen por publicar o difundir contenido comercial en la Aplicación del Barrio dirigido a sus Usuarios: publicidad, avisos, promociones, beneficios, patrocinios, avisos destacados, comisiones por ventas o reservas hechas desde la Aplicación, enlaces de afiliados u otros de naturaleza similar.',
    'b) No son Ingresos Comerciales: (i) lo que el Autor perciba por desarrollar, adaptar, mantener, alojar o licenciar la Aplicación u otras aplicaciones a terceros, incluidos otros barrios o instituciones; (ii) los honorarios o pagos que le hicieran el propio Barrio o la Asociación; (iii) las donaciones o aportes hechos al Autor a título personal; y (iv) los reintegros de gastos.',
    'c) Ingresos Comerciales Netos: los Ingresos Comerciales, menos (i) el impuesto al valor agregado y los demás tributos que graven directamente esos ingresos, incluidos el impuesto sobre los ingresos brutos y las tasas municipales; (ii) las comisiones y cargos de los medios de cobro; y (iii) las devoluciones, contracargos y bonificaciones efectivamente otorgadas. No se descuenta ningún otro gasto del Autor.',
  ]],
  ['Tercera. Períodos, entrega y rendición de cuentas', [
    'Los Ingresos Comerciales Netos se liquidan por semestre calendario (del 1 de enero al 30 de junio y del 1 de julio al 31 de diciembre). Dentro de los treinta (30) días corridos posteriores al cierre de cada semestre, el Autor: a) entrega a la Asociación un informe escrito, firmado, con la nómina de Anunciantes, el concepto y el monto de cada cobro, cada deducción con su respaldo y el monto que corresponde donar; y b) transfiere ese monto a la cuenta bancaria de titularidad de la Asociación que esta le indique por escrito. Si en un semestre no hubo Ingresos Comerciales, el informe lo dice.',
    'La Asociación entrega al Autor una constancia de recepción de cada donación, con fecha y monto. Cada entrega se perfecciona por la transferencia del dinero, como donación manual (art. 1554 del CCyC), y queda sujeta al cargo y a las condiciones de este compromiso.',
    'A pedido escrito de la Asociación, el Autor exhibe los comprobantes que emitió a los Anunciantes en el período informado. La Asociación guarda reserva sobre las condiciones comerciales pactadas con cada Anunciante.',
  ]],
  ['Cuarta. Cargo: destino de los fondos', [
    'La Asociación destinará los fondos donados exclusivamente a fines de bien común del Barrio: a) insumos médicos y de primeros auxilios, desfibriladores, botiquines y su mantenimiento y reposición, y la capacitación de vecinos y personal en primeros auxilios y RCP; b) la atención de emergencias y el equipamiento de prevención y seguridad (nieve, incendios, sismos y cortes de servicios); y c) actividades recreativas, deportivas, culturales y comunitarias abiertas a todos los vecinos.',
    'Los fondos no pueden destinarse a gastos ordinarios de administración ni a pagar, compensar o reducir expensas, y no pueden distribuirse entre los asociados (art. 168 del CCyC). El órgano de administración de la Asociación decide la aplicación concreta por acta; puede acumular fondos de varios semestres para una compra mayor, informando el saldo.',
  ]],
  ['Quinta. Transparencia', [
    'La Asociación registra los fondos en su contabilidad como donación con destino específico e identifica en qué se aplicó cada uno. Informa a sus asociados lo recibido y su aplicación al menos una vez al año, con la memoria y los estados contables o en la asamblea, y puede darlo a conocer en la Aplicación. El Autor puede pedir constancia de la aplicación de lo donado.',
    'Ambas partes conservan la documentación de este compromiso, de los informes y de las transferencias durante diez (10) años (art. 328 del CCyC).',
  ]],
  ['Sexta. Independencia de las partes', [
    'Este compromiso no constituye sociedad, asociación, contrato asociativo, relación laboral, mandato ni representación entre las partes. La Asociación no es parte de los contratos con los Anunciantes y no garantiza ni responde por ellos: el Autor contrata a su nombre y a su riesgo, factura lo que cobra y cumple sus propias obligaciones fiscales.',
    'Las donaciones no le dan al Autor derechos, preferencias ni influencia sobre las decisiones de la Asociación. Si el Autor integra alguno de sus órganos, se abstiene de votar en la aceptación, el destino y el control de estos fondos.',
  ]],
  ['Séptima. Publicidad responsable y datos personales', [
    'El Autor se obliga a: a) identificar cada anuncio como publicidad o promoción; b) no publicar publicidad engañosa, ilícita, discriminatoria o contraria al reglamento y a la convivencia del Barrio (art. 8 de la Ley 24.240, Decreto de Necesidad y Urgencia 274/2019 y Ley 23.592); c) no usar ni ceder los datos personales de los Usuarios para fines publicitarios, ni elegir los anuncios según quién mira, ni entregarlos a los Anunciantes (arts. 5, 11 y 27 de la Ley 25.326); y d) no instalar en la Aplicación rastreadores publicitarios de terceros.',
    'La Asociación, por medio de la Administración del Barrio, puede pedir fundadamente que se retire un anuncio. El Autor lo resuelve en un plazo de cinco (5) días hábiles.',
  ]],
  ['Octava. Vigencia y finalización', [
    'Este compromiso rige desde su firma y mientras la Aplicación esté en uso en el Barrio con espacios comerciales. Cualquiera de las partes puede ponerle fin con un preaviso escrito de sesenta (60) días. El fin no afecta las donaciones ya devengadas: lo correspondiente al período en curso se liquida dentro de los treinta (30) días siguientes.',
    'Si la Asociación diera a los fondos un destino distinto del pactado, el Autor puede intimarla por escrito a regularizarlo en treinta (30) días. Si no lo hace, puede revocar la donación respecto de los fondos mal aplicados por inejecución del cargo (art. 1569 del CCyC) y suspender las entregas siguientes hasta que se regularice.',
  ]],
  ['Novena. Forma y exigibilidad', [
    'Las partes firman este compromiso en dos ejemplares de un mismo tenor, con sus firmas certificadas por escribano público. Como las donaciones de prestaciones periódicas requieren escritura pública (art. 1552 del CCyC), cualquiera de las partes puede pedir que se otorgue por escritura pública, y la otra se obliga a prestarse a ello; los gastos de escrituración los afronta el Autor. Hasta entonces, este instrumento documenta la voluntad de las partes y las condiciones (destino, rendición de cuentas y transparencia) a las que queda sujeta cada entrega, que se perfecciona como donación manual.',
  ]],
  ['Décima. Domicilios, comunicaciones y jurisdicción', [
    'Las partes constituyen domicilio en los indicados al comienzo y aceptan como válidas las comunicaciones por correo electrónico a las direcciones que consignan al pie. Para cualquier controversia se someten a los tribunales ordinarios del Distrito Judicial Sur de la Provincia de Tierra del Fuego, Antártida e Islas del Atlántico Sur, con asiento en la ciudad de Ushuaia.',
  ]],
  ['Undécima. Aceptación', [
    'La Asociación acepta esta donación con cargo por resolución de su órgano de administración, cuya copia certificada se agrega como anexo.',
  ]],
];
const textoCompromiso = (tag = 'h3') => {
  const c = Store.s.config, b = esc(c.nombre || 'Bahía Cauquén');
  return COMPROMISO_APORTE.map(([t, ps]) => `<${tag}>${esc(t)}</${tag}>${ps.map(p => `<p>${esc(p).replace(/\{BARRIO\}/g, b)}</p>`).join('')}`).join('');
};
const cabCompromiso = () => { const c = Store.s.config;
  return `<p>En la ciudad de Ushuaia, Provincia de Tierra del Fuego, Antártida e Islas del Atlántico Sur, a los ____ días del mes de ______________ de 20____, entre:</p>
  <p><b>CLAUDIO A. RAVASI</b>, DNI ______________, CUIT ______________, con domicilio en ________________________________, Ushuaia (en adelante, "el Autor"); y</p>
  <p><b>ASOCIACIÓN CIVIL ______________________________</b> (Barrio ${esc(c.nombre || 'Bahía Cauquén')}), CUIT ${esc(c.cuit || '______________')}, con domicilio en ${esc(c.domicilio || '________________________________')}, representada en este acto por ________________________________, DNI ______________, en su carácter de ______________________, según su estatuto y el acta de su órgano de administración N.º ______ del ____/____/______ (en adelante, "la Asociación"),</p>
  <p>convienen celebrar el presente <b>compromiso de donación con cargo</b>, sujeto a los antecedentes y cláusulas que siguen.</p>`; };
const firmasCompromiso = () => `<div class="firma"><div>Claudio A. Ravasi<br>El Autor<br><small>Correo: ______________________</small></div><div>Por la Asociación Civil<br>Firma y aclaración<br><small>Correo: ______________________</small></div></div>`;
const PIE_COMPROMISO = 'Modelo redactado para el Barrio. Antes de firmarlo tiene que revisarlo un abogado matriculado en Tierra del Fuego y aprobarlo el órgano de administración de la Asociación Civil.';

const cfgAporte = () => Object.assign({ firmado:false, fecha:'', acta:'', escritura:false, entregas:[] }, Store.s.config.aporte || {});
const PERIODO_APORTE = p => { const [a, s] = String(p || '').split('-'); return a && s ? `${s === '1' ? '1.er' : '2.º'} semestre ${a}` : String(p || ''); };

R.aporte = {
  titulo:'Publicidad y aporte al barrio', icon:'heart', color:'ok', sub:'El 50 % de lo que pagan los comercios, para el bien común del barrio',
  render(){
    const a = cfgAporte(), ents = aLista(a.entregas).slice().sort((x, y) => String(y.periodo).localeCompare(String(x.periodo)));
    const total = ents.reduce((n, e) => n + (+e.monto || 0), 0);
    const punto = (ic, t, x) => `<div class="it"><span class="ic ic-ok" style="width:34px;height:34px;border-radius:11px;display:grid;place-items:center">${I(ic)}</span><div class="txt"><b>${t}</b><span style="white-space:normal">${x}</span></div></div>`;
    return `<div class="card lista">
        ${punto('check', 'La app es gratis', 'Ni el barrio ni los vecinos pagan nada por usarla.')}
        ${punto('star', 'Los comercios pueden publicar', 'Promociones, beneficios y publicidad, siempre marcados como tales. Lo que paguen lo cobra el autor de la app, Claudio A. Ravasi, que factura y paga sus impuestos.')}
        ${punto('heart', 'La mitad es para el barrio', 'El 50 % de lo cobrado, descontados solo los impuestos y las comisiones de cobro, se dona a la Asociación Civil del barrio.')}
        ${punto('siren', 'Para qué se usa', 'Insumos médicos y de primeros auxilios, el DEA y su mantenimiento, emergencias, prevención y seguridad, y actividades recreativas, deportivas y culturales para todos. Nunca para pagar expensas ni gastos de todos los días.')}
        ${punto('clock', 'Cada seis meses, por escrito', 'El autor entrega un informe con lo cobrado y transfiere el aporte a la cuenta de la Asociación, que da la constancia, decide en qué se usa por acta y lo informa a los vecinos al menos una vez por año.')}
        ${punto('lock', 'Tus datos no se venden', 'Ningún comercio recibe tus datos, y los anuncios no se eligen según quién sos.')}
      </div>
      <p class="muted small" style="margin:10px 2px 0">${I('info')} ¿Por qué una donación y no que cobre el barrio? La Asociación Civil no tiene fines de lucro: no vende publicidad ni firma con los comercios. Recibe una <b>donación con cargo</b>, es decir, con un destino obligatorio que se puede controlar.</p>
      ${sec('Estado del compromiso')}
      <div class="card">${a.firmado ? aviso('ok', 'check', 'Compromiso firmado', `${a.fecha ? 'El ' + fechaLarga(a.fecha) : ''}${a.acta ? ' · aceptado por acta N.º ' + esc(a.acta) : ''}${a.escritura ? ' · elevado a escritura pública' : ''}`)
        : aviso('warn', 'clock', 'Todavía sin firmar', 'Lo firman el autor y la Asociación Civil. Mientras tanto rige lo que dicen los términos de uso (punto 4).')}
        ${ents.length ? `<div class="garita-kpis" style="margin-top:10px"><div class="kpi"><b>${plata(total)}</b><span>Donado en total</span></div><div class="kpi"><b>${ents.length}</b><span>${ents.length === 1 ? 'Entrega' : 'Entregas'}</span></div></div>
          <div class="lista" style="margin-top:8px">${ents.map(e => `<div class="it"><div class="txt"><b>${esc(PERIODO_APORTE(e.periodo))} · ${plata(+e.monto || 0)}</b><span style="white-space:normal">${e.fecha ? 'Recibido el ' + fechaCorta(e.fecha) : ''}${e.destino ? ' · ' + esc(e.destino) : ''}</span></div>
            ${esAdmin() ? `<button class="icon-btn" data-a="aporte-borrar" data-id="${esc(e.id)}" aria-label="Borrar">${I('trash')}</button>` : ''}</div>`).join('')}</div>`
          : `<p class="muted small" style="margin:10px 0 0">Todavía no hubo donaciones. Cuando las haya, la Administración las anota acá con su destino.</p>`}</div>
      ${esAdmin() ? `<details class="plegable card" data-k="aporte-admin"><summary><b>Anotar (solo la Administración)</b><span class="muted small">firma y entregas</span></summary>
        <form data-f="aporte-estado" style="margin-top:10px">
          <label class="check"><input type="checkbox" name="firmado" ${a.firmado ? 'checked' : ''}><span>El compromiso está firmado</span></label>
          <div class="grid2"><div class="field"><label>Fecha de la firma</label><input type="date" name="fecha" value="${esc(a.fecha)}"></div><div class="field"><label>Acta de aceptación N.º</label><input name="acta" maxlength="30" value="${esc(a.acta)}"></div></div>
          <label class="check"><input type="checkbox" name="escritura" ${a.escritura ? 'checked' : ''}><span>Se elevó a escritura pública</span></label>
          <button class="btn btn-sec btn-block">${I('check')}Guardar el estado</button></form>
        <form data-f="aporte-entrega" style="margin-top:14px">
          <div class="grid2"><div class="field"><label>Semestre</label><select name="periodo">${(() => { const y = new Date().getFullYear(); return [y, y - 1].flatMap(an => [2, 1].map(s => `<option value="${an}-${s}">${PERIODO_APORTE(an + '-' + s)}</option>`)).join(''); })()}</select></div>
            <div class="field"><label>Monto recibido ($)</label><input name="monto" type="number" min="0" step="0.01" required></div></div>
          <div class="field"><label>Fecha en que se recibió</label><input type="date" name="fecha" value="${hoyISO()}" required></div>
          <div class="field"><label>En qué se aplicó o se va a aplicar</label><input name="destino" maxlength="160" placeholder="Ej: reposición del botiquín de la garita y parches del DEA"></div>
          <button class="btn btn-pri btn-block">${I('plus')}Anotar la entrega</button></form>
        <p class="muted tiny" style="margin:10px 0 0">Lo que se anota acá lo ven todos los vecinos (sin los nombres de los comercios). Queda en la auditoría.</p></details>` : ''}
      ${sec('El compromiso completo')}
      <details class="plegable card legal" data-k="compromiso"><summary><b>Compromiso de donación con cargo</b><span class="muted small">leer</span></summary>
        <div style="margin-top:10px"><p class="legal-cab"><b>Compromiso de donación con cargo de los ingresos comerciales de la aplicación "Barrio ${esc(Store.s.config.nombre || 'Bahía Cauquén')}"</b><span>Modelo para firmar entre el autor y la Asociación Civil</span></p>
        ${cabCompromiso()}${textoCompromiso()}<p class="muted tiny">${esc(PIE_COMPROMISO)}</p></div></details>
      <div class="btns" style="margin-top:12px"><button class="btn btn-pri grow" data-a="compromiso-pdf">${I('download')}Descargar o imprimir para firmar</button>
        <button class="btn btn-sec grow" data-a="abrir" data-v="legal">${I('file')}Términos de uso (punto 4)</button></div>`;
  },
};
A['compromiso-pdf'] = () => imprimir('Compromiso de donación con cargo', `<h1>Compromiso de donación con cargo</h1>
  <p><b>Ingresos comerciales de la aplicación "Barrio ${esc(Store.s.config.nombre || 'Bahía Cauquén')}" · aporte del 50 % a la Asociación Civil del Barrio</b></p>
  ${cabCompromiso()}${textoCompromiso('h2')}${firmasCompromiso()}`, { pie:PIE_COMPROMISO });
F['aporte-estado'] = d => {
  if (!esAdmin()) return;
  Store.cambiar(s => { s.config.aporte = Object.assign({}, cfgAporte(), { firmado:!!d.firmado, fecha:d.fecha || '', acta:String(d.acta || '').trim(), escritura:!!d.escritura });
    auditar(s, 'Actualizó el estado del compromiso de donación (publicidad)', d.firmado ? 'Firmado' + (d.fecha ? ' el ' + d.fecha : '') : 'Sin firmar'); });
  toast('Guardado', 'check'); refrescar();
};
F['aporte-entrega'] = (d, form) => {
  if (!esAdmin()) return;
  const monto = Math.round(+d.monto * 100) / 100;
  if (!(monto >= 0)){ toast('Revisá el monto', 'alert'); return; }
  Store.cambiar(s => { const a = cfgAporte();
    s.config.aporte = Object.assign({}, a, { entregas:[...aLista(a.entregas), { id:uid(), periodo:d.periodo, monto, fecha:d.fecha, destino:String(d.destino || '').trim(), at:Date.now() }] });
    auditar(s, 'Anotó una donación de la publicidad de la app', `${PERIODO_APORTE(d.periodo)} · ${plata(monto)}`); });
  form.reset(); toast('Entrega anotada', 'heart'); refrescar();
};
A['aporte-borrar'] = async el => {
  if (!esAdmin() || !await confirmar('Borrar la entrega', 'Se borra este renglón del registro de donaciones. Queda en la auditoría.', { si:'Borrar', peligro:true })) return;
  Store.cambiar(s => { const a = cfgAporte(), e = aLista(a.entregas).find(x => x.id === el.dataset.id);
    s.config.aporte = Object.assign({}, a, { entregas:aLista(a.entregas).filter(x => x.id !== el.dataset.id) });
    if (e) auditar(s, 'Borró una donación del registro (publicidad)', `${PERIODO_APORTE(e.periodo)} · ${plata(+e.monto || 0)}`); });
  refrescar();
};
